### 2. Complete C++20 Implementation

```cpp
#include <iostream>
#include <atomic>
#include <memory>
#include <optional>
#include <vector>
#include <array>
#include <random>
#include <thread>
#include <chrono>
#include <functional>
#include <concepts>
#include <cstdint>
#include <cassert>
#include <new>

#if defined(__cpp_lib_hardware_interference_size)
    using std::hardware_destructive_interference_size;
#else
    // Standard x86-64 / ARM cache-line size fallback
    constexpr size_t hardware_destructive_interference_size = 64;
#endif

// ============================================================================
// 1. EPOCH-BASED RECLAMATION (EBR) FRAMEWORK
// ============================================================================

class EpochManager {
public:
    static constexpr size_t MAX_THREADS = 128;
    static constexpr size_t RETIRE_THRESHOLD = 64;
    static constexpr uint64_t EPOCH_INACTIVE = std::numeric_limits<uint64_t>::max();

    struct alignas(hardware_destructive_interference_size) ThreadControlBlock {
        std::atomic<uint64_t> local_epoch{EPOCH_INACTIVE};
        std::atomic<bool> is_active{false};
        std::atomic<bool> registered{false};
    };

    struct RetiredObject {
        void* ptr{nullptr};
        void (*deleter)(void*){nullptr};
        uint64_t retire_epoch{0};
        RetiredObject* next{nullptr};
    };

    struct alignas(hardware_destructive_interference_size) ThreadLocalLimbo {
        RetiredObject* head{nullptr};
        size_t count{0};
    };

private:
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_{0};
    std::array<ThreadControlBlock, MAX_THREADS> tcbs_{};
    static inline thread_local size_t tl_thread_id = std::numeric_limits<size_t>::max();
    static inline thread_local ThreadLocalLimbo tl_limbo{};

public:
    EpochManager() = default;
    ~EpochManager() {
        // Drain any remaining allocated limbo memory across all epochs
        ForceDrainAll();
    }

    EpochManager(const EpochManager&) = delete;
    EpochManager& operator=(const EpochManager&) = delete;

    static EpochManager& Instance() {
        static EpochManager instance;
        return instance;
    }

    size_t RegisterThread() {
        if (tl_thread_id != std::numeric_limits<size_t>::max()) {
            return tl_thread_id;
        }
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            bool expected = false;
            if (tcbs_[i].registered.compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
                tl_thread_id = i;
                return i;
            }
        }
        throw std::runtime_error("EpochManager: Max registered threads exceeded.");
    }

    void UnregisterThread() {
        if (tl_thread_id < MAX_THREADS) {
            FlushLimbo(true);
            tcbs_[tl_thread_id].local_epoch.store(EPOCH_INACTIVE, std::memory_order_release);
            tcbs_[tl_thread_id].is_active.store(false, std::memory_order_release);
            tcbs_[tl_thread_id].registered.store(false, std::memory_order_release);
            tl_thread_id = std::numeric_limits<size_t>::max();
        }
    }

    void EnterCriticalSection() {
        RegisterThread();
        tcbs_[tl_thread_id].is_active.store(true, std::memory_order_relaxed);
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_acquire);
        tcbs_[tl_thread_id].local_epoch.store(cur_epoch, std::memory_order_release);
    }

    void LeaveCriticalSection() {
        if (tl_thread_id < MAX_THREADS) {
            tcbs_[tl_thread_id].local_epoch.store(EPOCH_INACTIVE, std::memory_order_release);
            tcbs_[tl_thread_id].is_active.store(false, std::memory_order_release);
            if (tl_limbo.count >= RETIRE_THRESHOLD) {
                TryAdvanceAndReclaim();
            }
        }
    }

    template <typename T>
    void Retire(T* ptr) {
        if (!ptr) return;
        RegisterThread();
        auto obj = new RetiredObject{
            .ptr = static_cast<void*>(ptr),
            .deleter = [](void* p) { delete static_cast<T*>(p); },
            .retire_epoch = global_epoch_.load(std::memory_order_relaxed),
            .next = tl_limbo.head
        };
        tl_limbo.head = obj;
        tl_limbo.count++;

        if (tl_limbo.count >= RETIRE_THRESHOLD) {
            TryAdvanceAndReclaim();
        }
    }

    void TryAdvanceAndReclaim() {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_acquire);

        // Check if all active threads have caught up to cur_epoch
        bool can_advance = true;
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (tcbs_[i].registered.load(std::memory_order_relaxed) &&
                tcbs_[i].is_active.load(std::memory_order_acquire)) {
                uint64_t th_epoch = tcbs_[i].local_epoch.load(std::memory_order_acquire);
                if (th_epoch != EPOCH_INACTIVE && th_epoch < cur_epoch) {
                    can_advance = false;
                    break;
                }
            }
        }

        if (can_advance) {
            global_epoch_.compare_exchange_strong(cur_epoch, cur_epoch + 1, std::memory_order_acq_rel);
        }

        FlushLimbo(false);
    }

    void FlushLimbo(bool force_all) {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_acquire);
        RetiredObject** curr = &tl_limbo.head;

        while (*curr != nullptr) {
            RetiredObject* entry = *curr;
            // Memory safe to delete if retire_epoch + 2 <= cur_epoch
            if (force_all || (entry->retire_epoch + 2 <= cur_epoch)) {
                *curr = entry->next;
                entry->deleter(entry->ptr);
                delete entry;
                tl_limbo.count--;
            } else {
                curr = &(entry->next);
            }
        }
    }

    void ForceDrainAll() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            tcbs_[i].local_epoch.store(EPOCH_INACTIVE, std::memory_order_relaxed);
            tcbs_[i].is_active.store(false, std::memory_order_relaxed);
        }
        global_epoch_.fetch_add(10, std::memory_order_seq_cst);
        FlushLimbo(true);
    }
};

class EpochGuard {
public:
    EpochGuard() { EpochManager::Instance().EnterCriticalSection(); }
    ~EpochGuard() { EpochManager::Instance().LeaveCriticalSection(); }
    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
};

// ============================================================================
// 2. TAGGED MARKABLE POINTER UTILITY
// ============================================================================

template <typename T>
class MarkablePointer {
private:
    uintptr_t bits_{0};
    static constexpr uintptr_t MARK_MASK = 0x1;
    static constexpr uintptr_t PTR_MASK = ~MARK_MASK;

public:
    constexpr MarkablePointer() noexcept : bits_(0) {}
    constexpr MarkablePointer(T* ptr, bool mark = false) noexcept
        : bits_(reinterpret_cast<uintptr_t>(ptr) | (mark ? MARK_MASK : 0)) {}

    [[nodiscard]] inline T* GetPtr() const noexcept {
        return reinterpret_cast<T*>(bits_ & PTR_MASK);
    }

    [[nodiscard]] inline bool IsMarked() const noexcept {
        return (bits_ & MARK_MASK) != 0;
    }

    [[nodiscard]] inline uintptr_t Raw() const noexcept {
        return bits_;
    }

    bool operator==(const MarkablePointer& other) const noexcept = default;
};

// ============================================================================
// 3. MVCC NODE DEFINITIONS
// ============================================================================

template <typename V>
struct VersionNode {
    uint64_t commit_ts;
    std::optional<V> payload; // std::nullopt represents a tombstone
    std::atomic<VersionNode<V>*> next_version{nullptr};

    VersionNode(uint64_t ts, std::optional<V> val)
        : commit_ts(ts), payload(std::move(val)), next_version(nullptr) {}
};

template <typename K, typename V>
struct alignas(hardware_destructive_interference_size) IndexNode {
    K key;
    size_t height;
    std::atomic<VersionNode<V>*> versions{nullptr};
    std::array<std::atomic<MarkablePointer<IndexNode<K, V>>>, 32> forward;

    IndexNode(const K& k, size_t h, VersionNode<V>* init_version = nullptr)
        : key(k), height(h), versions(init_version) {
        for (size_t i = 0; i < 32; ++i) {
            forward[i].store(MarkablePointer<IndexNode<K, V>>(nullptr, false), std::memory_order_relaxed);
        }
    }

    IndexNode(K&& k, size_t h, VersionNode<V>* init_version = nullptr)
        : key(std::move(k)), height(h), versions(init_version) {
        for (size_t i = 0; i < 32; ++i) {
            forward[i].store(MarkablePointer<IndexNode<K, V>>(nullptr, false), std::memory_order_relaxed);
        }
    }
};

// ============================================================================
// 4. LOCK-FREE MVCC SKIP-LIST IMPLEMENTATION
// ============================================================================

template <
    typename K,
    typename V,
    typename Comp = std::less<K>
> requires std::strict_weak_order<Comp, K, K>
class MVCCSkipList {
public:
    static constexpr size_t MAX_HEIGHT = 32;
    static constexpr double PROBABILITY = 0.25;

private:
    Comp comp_{};
    IndexNode<K, V>* head_{nullptr};
    std::atomic<size_t> max_active_height_{1};

    size_t RandomHeight() noexcept {
        thread_local std::mt19937_64 rng(std::random_device{}() ^ std::hash<std::thread::id>{}(std::this_thread::get_id()));
        thread_local std::geometric_distribution<size_t> dist(1.0 - PROBABILITY);
        size_t h = dist(rng) + 1;
        return std::min(h, MAX_HEIGHT);
    }

    bool KeyEqual(const K& a, const K& b) const noexcept {
        return !comp_(a, b) && !comp_(b, a);
    }

    bool KeyLess(const K& a, const K& b) const noexcept {
        return comp_(a, b);
    }

    /**
     * Harris-Michael lock-free skip-list search & physical deletion helper.
     * Guaranteed to return unmarked predecessors and successors.
     */
    bool SearchInternal(
        const K& key,
        std::array<IndexNode<K, V>*, MAX_HEIGHT>& preds,
        std::array<IndexNode<K, V>*, MAX_HEIGHT>& succs
    ) noexcept {
        IndexNode<K, V>* pred = nullptr;
        IndexNode<K, V>* curr = nullptr;
        IndexNode<K, V>* succ = nullptr;

    retry:
        pred = head_;
        size_t highest_level = max_active_height_.load(std::memory_order_relaxed);

        for (int level = static_cast<int>(highest_level) - 1; level >= 0; --level) {
            MarkablePointer<IndexNode<K, V>> curr_mp = pred->forward[level].load(std::memory_order_acquire);

            while (true) {
                curr = curr_mp.GetPtr();
                if (!curr) break;

                MarkablePointer<IndexNode<K, V>> succ_mp = curr->forward[level].load(std::memory_order_acquire);

                // If curr is logically marked for deletion, physically unlink it
                while (succ_mp.IsMarked()) {
                    succ = succ_mp.GetPtr();
                    MarkablePointer<IndexNode<K, V>> expected(curr, false);
                    MarkablePointer<IndexNode<K, V>> desired(succ, false);

                    if (!pred->forward[level].compare_exchange_strong(
                            expected, desired, std::memory_order_acq_rel, std::memory_order_acquire)) {
                        goto retry;
                    }

                    // Level 0 unlinking triggers EBR retirement
                    if (level == 0) {
                        EpochManager::Instance().Retire(curr);
                    }

                    curr = succ;
                    if (!curr) break;
                    succ_mp = curr->forward[level].load(std::memory_order_acquire);
                }

                if (!curr) break;

                if (KeyLess(curr->key, key)) {
                    pred = curr;
                    curr_mp = succ_mp;
                } else {
                    break;
                }
            }
            preds[level] = pred;
            succs[level] = curr;
        }

        return (succs[0] != nullptr && KeyEqual(succs[0]->key, key));
    }

public:
    MVCCSkipList(Comp comp = Comp())
        : comp_(comp),
          head_(new IndexNode<K, V>(K{}, MAX_HEIGHT, nullptr)) {
        for (size_t i = 0; i < MAX_HEIGHT; ++i) {
            head_->forward[i].store(MarkablePointer<IndexNode<K, V>>(nullptr, false), std::memory_order_relaxed);
        }
    }

    ~MVCCSkipList() {
        EpochGuard guard;
        IndexNode<K, V>* curr = head_->forward[0].load(std::memory_order_relaxed).GetPtr();
        while (curr) {
            IndexNode<K, V>* next = curr->forward[0].load(std::memory_order_relaxed).GetPtr();
            // Free version chains
            VersionNode<V>* vcurr = curr->versions.load(std::memory_order_relaxed);
            while (vcurr) {
                VersionNode<V>* vnext = vcurr->next_version.load(std::memory_order_relaxed);
                delete vcurr;
                vcurr = vnext;
            }
            delete curr;
            curr = next;
        }
        delete head_;
    }

    MVCCSkipList(const MVCCSkipList&) = delete;
    MVCCSkipList& operator=(const MVCCSkipList&) = delete;

    /**
     * Put: Inserts a new version for `key` at `commit_ts`.
     */
    template <typename ValueType>
    bool Put(const K& key, ValueType&& value, uint64_t commit_ts) {
        EpochGuard guard;
        std::array<IndexNode<K, V>*, MAX_HEIGHT> preds;
        std::array<IndexNode<K, V>*, MAX_HEIGHT> succs;

        auto* new_version = new VersionNode<V>(commit_ts, std::forward<ValueType>(value));

        while (true) {
            bool found = SearchInternal(key, preds, succs);
            if (found) {
                IndexNode<K, V>* target = succs[0];
                VersionNode<V>* cur_vhead = target->versions.load(std::memory_order_acquire);

                if (cur_vhead && cur_vhead->commit_ts >= commit_ts) {
                    // Commit timestamp inversion check
                    delete new_version;
                    return false;
                }

                new_version->next_version.store(cur_vhead, std::memory_order_relaxed);
                if (target->versions.compare_exchange_weak(
                        cur_vhead, new_version, std::memory_order_release, std::memory_order_acquire)) {
                    return true;
                }
                // Version CAS failed; retry loop
                continue;
            }

            // Key does not exist; insert new IndexNode
            size_t height = RandomHeight();
            size_t current_max = max_active_height_.load(std::memory_order_relaxed);
            while (height > current_max) {
                if (max_active_height_.compare_exchange_weak(current_max, height, std::memory_order_relaxed)) {
                    break;
                }
            }

            auto* new_node = new IndexNode<K, V>(key, height, new_version);
            for (size_t i = 0; i < height; ++i) {
                new_node->forward[i].store(MarkablePointer<IndexNode<K, V>>(succs[i], false), std::memory_order_relaxed);
            }

            // Splice bottom level first
            MarkablePointer<IndexNode<K, V>> expected(succs[0], false);
            MarkablePointer<IndexNode<K, V>> desired(new_node, false);

            if (!preds[0]->forward[0].compare_exchange_strong(
                    expected, desired, std::memory_order_acq_rel, std::memory_order_acquire)) {
                // Splicing level 0 failed; retry search
                delete new_node;
                continue;
            }

            // Splice remaining higher levels
            for (size_t i = 1; i < height; ++i) {
                while (true) {
                    MarkablePointer<IndexNode<K, V>> exp(succs[i], false);
                    MarkablePointer<IndexNode<K, V>> des(new_node, false);
                    if (preds[i]->forward[i].compare_exchange_strong(
                            exp, des, std::memory_order_acq_rel, std::memory_order_acquire)) {
                        break;
                    }
                    // Re-search prefix to update preds and succs for higher level
                    SearchInternal(key, preds, succs);
                }
            }
            return true;
        }
    }

    /**
     * Delete: Appends a tombstone version at `commit_ts`.
     */
    bool Delete(const K& key, uint64_t commit_ts) {
        EpochGuard guard;
        std::array<IndexNode<K, V>*, MAX_HEIGHT> preds;
        std::array<IndexNode<K, V>*, MAX_HEIGHT> succs;

        auto* tombstone = new VersionNode<V>(commit_ts, std::nullopt);

        while (true) {
            bool found = SearchInternal(key, preds, succs);
            if (found) {
                IndexNode<K, V>* target = succs[0];
                VersionNode<V>* cur_vhead = target->versions.load(std::memory_order_acquire);

                if (cur_vhead && cur_vhead->commit_ts >= commit_ts) {
                    delete tombstone;
                    return false;
                }

                tombstone->next_version.store(cur_vhead, std::memory_order_relaxed);
                if (target->versions.compare_exchange_weak(
                        cur_vhead, tombstone, std::memory_order_release, std::memory_order_acquire)) {
                    return true;
                }
                continue;
            }

            // Key does not exist; insert an IndexNode with a tombstone version
            size_t height = RandomHeight();
            size_t current_max = max_active_height_.load(std::memory_order_relaxed);
            while (height > current_max) {
                if (max_active_height_.compare_exchange_weak(current_max, height, std::memory_order_relaxed)) {
                    break;
                }
            }

            auto* new_node = new IndexNode<K, V>(key, height, tombstone);
            for (size_t i = 0; i < height; ++i) {
                new_node->forward[i].store(MarkablePointer<IndexNode<K, V>>(succs[i], false), std::memory_order_relaxed);
            }

            MarkablePointer<IndexNode<K, V>> expected(succs[0], false);
            MarkablePointer<IndexNode<K, V>> desired(new_node, false);

            if (!preds[0]->forward[0].compare_exchange_strong(
                    expected, desired, std::memory_order_acq_rel, std::memory_order_acquire)) {
                delete new_node;
                continue;
            }

            for (size_t i = 1; i < height; ++i) {
                while (true) {
                    MarkablePointer<IndexNode<K, V>> exp(succs[i], false);
                    MarkablePointer<IndexNode<K, V>> des(new_node, false);
                    if (preds[i]->forward[i].compare_exchange_strong(
                            exp, des, std::memory_order_acq_rel, std::memory_order_acquire)) {
                        break;
                    }
                    SearchInternal(key, preds, succs);
                }
            }
            return true;
        }
    }

    /**
     * Get: Lock-free, wait-free population-oblivious point lookup at read_ts.
     */
    [[nodiscard]] std::optional<V> Get(const K& key, uint64_t read_ts) const noexcept {
        EpochGuard guard;
        IndexNode<K, V>* pred = head_;
        size_t highest_level = max_active_height_.load(std::memory_order_relaxed);

        for (int level = static_cast<int>(highest_level) - 1; level >= 0; --level) {
            MarkablePointer<IndexNode<K, V>> curr_mp = pred->forward[level].load(std::memory_order_acquire);
            while (curr_mp.GetPtr() != nullptr) {
                IndexNode<K, V>* curr = curr_mp.GetPtr();
                if (KeyLess(curr->key, key)) {
                    pred = curr;
                    curr_mp = curr->forward[level].load(std::memory_order_acquire);
                } else {
                    break;
                }
            }
        }

        IndexNode<K, V>* target = pred->forward[0].load(std::memory_order_acquire).GetPtr();
        if (!target || !KeyEqual(target->key, key)) {
            return std::nullopt;
        }

        // Traverse lock-free version chain
        VersionNode<V>* vcurr = target->versions.load(std::memory_order_acquire);
        while (vcurr != nullptr) {
            if (vcurr->commit_ts <= read_ts) {
                return vcurr->payload; // Returns std::nullopt if tombstone
            }
            vcurr = vcurr->next_version.load(std::memory_order_acquire);
        }

        return std::nullopt;
    }

    /**
     * Scan: Atomic snapshot linearizable range scan in [start_key, end_key).
     */
    [[nodiscard]] std::vector<std::pair<K, V>> Scan(
        const K& start_key,
        const std::optional<K>& end_key,
        uint64_t read_ts,
        size_t limit = std::numeric_limits<size_t>::max()
    ) const {
        EpochGuard guard;
        std::vector<std::pair<K, V>> results;
        if (limit == 0) return results;

        IndexNode<K, V>* pred = head_;
        size_t highest_level = max_active_height_.load(std::memory_order_relaxed);

        // Fast descend to start_key
        for (int level = static_cast<int>(highest_level) - 1; level >= 0; --level) {
            MarkablePointer<IndexNode<K, V>> curr_mp = pred->forward[level].load(std::memory_order_acquire);
            while (curr_mp.GetPtr() != nullptr) {
                IndexNode<K, V>* curr = curr_mp.GetPtr();
                if (KeyLess(curr->key, start_key)) {
                    pred = curr;
                    curr_mp = curr->forward[level].load(std::memory_order_acquire);
                } else {
                    break;
                }
            }
        }

        IndexNode<K, V>* curr = pred->forward[0].load(std::memory_order_acquire).GetPtr();

        while (curr != nullptr && results.size() < limit) {
            if (end_key.has_value() && !KeyLess(curr->key, *end_key)) {
                break;
            }

            // Inspect version chain for current node
            VersionNode<V>* vcurr = curr->versions.load(std::memory_order_acquire);
            while (vcurr != nullptr) {
                if (vcurr->commit_ts <= read_ts) {
                    if (vcurr->payload.has_value()) {
                        results.emplace_back(curr->key, *vcurr->payload);
                    }
                    break;
                }
                vcurr = vcurr->next_version.load(std::memory_order_acquire);
            }

            curr = curr->forward[0].load(std::memory_order_acquire).GetPtr();
        }

        return results;
    }

    /**
     * PruneVersions: Compaction step unlinking versions strictly older than watermark_ts.
     */
    void PruneVersions(uint64_t watermark_ts) {
        EpochGuard guard;
        IndexNode<K, V>* curr = head_->forward[0].load(std::memory_order_acquire).GetPtr();

        while (curr != nullptr) {
            VersionNode<V>* vhead = curr->versions.load(std::memory_order_acquire);
            VersionNode<V>* vprev = nullptr;
            VersionNode<V>* vcurr = vhead;

            // Retain at most one version older than watermark_ts as the base visible snapshot
            bool keep_next_older = true;

            while (vcurr != nullptr) {
                if (vcurr->commit_ts < watermark_ts) {
                    if (keep_next_older) {
                        keep_next_older = false;
                        vprev = vcurr;
                        vcurr = vcurr->next_version.load(std::memory_order_acquire);
                    } else {
                        // Unlink all subsequent older versions
                        if (vprev) {
                            VersionNode<V>* obsolete_chain = vcurr;
                            vprev->next_version.store(nullptr, std::memory_order_release);

                            // Retire unlinked chain into EBR
                            while (obsolete_chain != nullptr) {
                                VersionNode<V>* vnext = obsolete_chain->next_version.load(std::memory_order_relaxed);
                                EpochManager::Instance().Retire(obsolete_chain);
                                obsolete_chain = vnext;
                            }
                        }
                        break;
                    }
                } else {
                    vprev = vcurr;
                    vcurr = vcurr->next_version.load(std::memory_order_acquire);
                }
            }

            curr = curr->forward[0].load(std::memory_order_acquire).GetPtr();
        }
    }
};

// ============================================================================
// 5. VALIDATION & STRESS HARNESS
// ============================================================================

void RunLinearizabilityStressTest() {
    std::cout << "\n=========================================\n";
    std::cout << "Starting Test 1: Monotonic Snapshot Linearizability\n";
    std::cout << "=========================================\n";

    MVCCSkipList<int, int> sl;
    constexpr int NUM_WRITERS = 4;
    constexpr int NUM_READERS = 4;
    constexpr int KEYS = 100;
    constexpr int OPS_PER_THREAD = 5000;

    std::atomic<bool> running{true};
    std::atomic<uint64_t> global_ts{1};

    // Writers concurrently insert incrementing versions
    std::vector<std::thread> writers;
    for (int tid = 0; tid < NUM_WRITERS; ++tid) {
        writers.emplace_back([&, tid]() {
            for (int i = 0; i < OPS_PER_THREAD; ++i) {
                int key = (i + tid * 1000) % KEYS;
                uint64_t ts = global_ts.fetch_add(1, std::memory_order_relaxed);
                sl.Put(key, static_cast<int>(ts), ts);
            }
        });
    }

    // Readers concurrently perform snapshot range scans and verify linear monotonicity
    std::vector<std::thread> readers;
    std::atomic<uint64_t> total_scans{0};
    for (int tid = 0; tid < NUM_READERS; ++tid) {
        readers.emplace_back([&]() {
            while (running.load(std::memory_order_relaxed)) {
                uint64_t read_ts = global_ts.load(std::memory_order_relaxed);
                auto res = sl.Scan(0, KEYS, read_ts);
                for (const auto& [k, v] : res) {
                    assert(static_cast<uint64_t>(v) <= read_ts && "Linearizability violation: read value from future!");
                }
                total_scans.fetch_add(1, std::memory_order_relaxed);
            }
        });
    }

    for (auto& w : writers) w.join();
    running.store(false);
    for (auto& r : readers) r.join();

    std::cout << "Passed. Executed " << total_scans.load() << " consistent snapshot range scans.\n";
}

void RunMixedWorkloadHighContentionTest() {
    std::cout << "\n=========================================\n";
    std::cout << "Starting Test 2: High Contention Mixed Workload (16 Threads)\n";
    std::cout << "Workload profile: 80% Get, 15% Put/Delete, 5% Scan\n";
    std::cout << "=========================================\n";

    MVCCSkipList<int, std::string> sl;
    constexpr int NUM_THREADS = 16;
    constexpr int DURATION_SEC = 3;
    constexpr int KEY_RANGE = 200;

    std::atomic<bool> running{true};
    std::atomic<uint64_t> global_ts{1};
    std::atomic<uint64_t> read_ops{0};
    std::atomic<uint64_t> write_ops{0};
    std::atomic<uint64_t> scan_ops{0};

    auto worker = [&](int tid) {
        std::mt19937 rng(tid ^ 0xDEADBEEF);
        std::uniform_int_distribution<int> op_dist(1, 100);
        std::uniform_int_distribution<int> key_dist(1, KEY_RANGE);

        while (running.load(std::memory_order_relaxed)) {
            int roll = op_dist(rng);
            int k = key_dist(rng);

            if (roll <= 80) { // 80% Get
                uint64_t r_ts = global_ts.load(std::memory_order_relaxed);
                auto val = sl.Get(k, r_ts);
                read_ops.fetch_add(1, std::memory_order_relaxed);
            } else if (roll <= 95) { // 15% Put/Delete
                uint64_t w_ts = global_ts.fetch_add(1, std::memory_order_relaxed);
                if (roll % 2 == 0) {
                    sl.Put(k, "val_" + std::to_string(w_ts), w_ts);
                } else {
                    sl.Delete(k, w_ts);
                }
                write_ops.fetch_add(1, std::memory_order_relaxed);
            } else { // 5% Range Scan
                uint64_t r_ts = global_ts.load(std::memory_order_relaxed);
                auto res = sl.Scan(k, k + 20, r_ts, 10);
                scan_ops.fetch_add(1, std::memory_order_relaxed);
            }
        }
    };

    std::vector<std::thread> threads;
    threads.reserve(NUM_THREADS);
    for (int i = 0; i < NUM_THREADS; ++i) {
        threads.emplace_back(worker, i);
    }

    std::this_thread::sleep_for(std::chrono::seconds(DURATION_SEC));
    running.store(false);

    for (auto& t : threads) t.join();

    uint64_t total = read_ops + write_ops + scan_ops;
    std::cout << "Done.\n"
              << "  Total Operations: " << total << " (" << total / DURATION_SEC << " ops/sec)\n"
              << "  Reads (Get):      " << read_ops.load() << "\n"
              << "  Writes (Put/Del): " << write_ops.load() << "\n"
              << "  Scans (Scan):     " << scan_ops.load() << "\n";
}

void RunEBRAndPruningStressTest() {
    std::cout << "\n=========================================\n";
    std::cout << "Starting Test 3: Version Pruning & EBR Memory Reclamation\n";
    std::cout << "=========================================\n";

    MVCCSkipList<int, int> sl;
    constexpr int NUM_ITERATIONS = 50000;

    for (int i = 1; i <= NUM_ITERATIONS; ++i) {
        sl.Put(42, i, i);
    }

    assert(sl.Get(42, NUM_ITERATIONS) == NUM_ITERATIONS);
    assert(sl.Get(42, 100) == 100);

    std::cout << "Unlinking versions older than watermark TS = " << (NUM_ITERATIONS - 50) << "...\n";
    sl.PruneVersions(NUM_ITERATIONS - 50);

    // Drain epochs and ensure safe memory release
    EpochManager::Instance().ForceDrainAll();

    // Verify recent version reads remain fully accessible
    assert(sl.Get(42, NUM_ITERATIONS) == NUM_ITERATIONS);
    assert(sl.Get(42, NUM_ITERATIONS - 10) == NUM_ITERATIONS - 10);

    std::cout << "Pruning & reclamation executed successfully with zero leaks or use-after-free.\n";
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cout << "==================================================================\n";
    std::cout << "Lock-Free MVCC Skip-List with Epoch-Based Reclamation (C++20)\n";
    std::cout << "==================================================================\n";

    RunLinearizabilityStressTest();
    RunMixedWorkloadHighContentionTest();
    RunEBRAndPruningStressTest();

    std::cout << "\nAll verification suites completed successfully.\n";
    return 0;
}
